template:
// 1. Merge overlapping intervals. Touching counts as overlap here (<=).
vector<vector<int>> merge(vector<vector<int>>& iv) {
    sort(iv.begin(), iv.end());                        // by start, then end
    vector<vector<int>> out;
    for (auto& x : iv) {
        if (!out.empty() && x[0] <= out.back()[1])     // overlaps the last kept block
            out.back()[1] = max(out.back()[1], x[1]);  // extend — max, not x[1]
        else out.push_back(x);
    }
    return out;
}

// 2. Minimum rooms / max concurrent: min-heap of end times.
int minRooms(vector<vector<int>>& iv) {
    sort(iv.begin(), iv.end());
    priority_queue<int, vector<int>, greater<int>> ends;
    int best = 0;
    for (auto& x : iv) {
        while (!ends.empty() && ends.top() <= x[0]) ends.pop();   // rooms that freed up
        ends.push(x[1]);
        best = max(best, (int)ends.size());
    }
    return best;
}

// 2b. Same question as a sweep line: +1 at start, -1 at end.
int maxConcurrent(vector<vector<int>>& iv) {
    vector<pair<int,int>> ev;                          // (time, delta); -1 sorts before +1 at ties
    for (auto& x : iv) { ev.push_back({x[0], +1}); ev.push_back({x[1], -1}); }
    sort(ev.begin(), ev.end());
    int cur = 0, best = 0;
    for (auto& [t, d] : ev) { cur += d; best = max(best, cur); }
    return best;
}

// 3. Maximum non-overlapping set (== min removals): sort by END, greedy.
int eraseOverlapIntervals(vector<vector<int>>& iv) {
    sort(iv.begin(), iv.end(), [](auto& a, auto& b) { return a[1] < b[1]; });
    int kept = 0; long long lastEnd = LLONG_MIN;
    for (auto& x : iv)
        if (x[0] >= lastEnd) { ++kept; lastEnd = x[1]; }  // starts after the earliest-ending kept one
    return (int)iv.size() - kept;
}
